// === Tab: mySketch ===
let dataOrder
let dataDisorder
let particle
let particleShader
let scratch
let prev, next
let remapColors
async function setup() {
	const cnv = createCanvas(windowWidth, windowHeight, WEBGL)
	prev = createFramebuffer()
	next = createFramebuffer()
	const font = await loadFont('https://fonts.gstatic.com/s/archivonarrow/v35/tss5ApVBdCYD5Q7hcxTE1ArZ0Zz8oY2KRmwvKhhvLFGKpHOtFCQ76Q.ttf')
	dataOrder = createFramebuffer({ width: 100, height: 100, density: 1, format: FLOAT })
	dataDisorder = createFramebuffer({ width: 100, height: 100, density: 1, format: FLOAT })

	scratch = createFramebuffer({ density: 1, width: ceil(width / 4), height: ceil(height / 4) })
	textFont(font)
	textAlign(CENTER, CENTER)
	textSize(width/5/4)

	for (const [i, data] of [dataOrder, dataDisorder].entries()) {
		const txt = i === 0 ? 'ORDER' : 'DISORDER'
		scratch.draw(() => {
			background(255)
			fill(0)
			text(txt, 0, 0)
		})
		scratch.loadPixels()
		data.loadPixels()
		for (let x = 0; x < data.width; x++) {
			for (let y = 0; y < data.height; y++) {
				let sx, sy
				do {
					sx = random(scratch.width)
					sy = random(scratch.height)
				} while (scratch.pixels[(floor(sy) * scratch.width + floor(sx)) * 4] > 100)

				data.pixels[(data.width * y + x) * 4 + 0] = sx/scratch.width
				data.pixels[(data.width * y + x) * 4 + 1] = sy/scratch.height
				data.pixels[(data.width * y + x) * 4 + 2] = 0
				data.pixels[(data.width * y + x) * 4 + 3] = 1
			}
		}
		cnv.getTexture(data).setInterpolation(NEAREST, NEAREST)
		data.updatePixels()
	}

	particle = buildGeometry(() => {
		noStroke()
		circle(0, 0, 5)
	})

	particleShader = baseColorShader().modify({
		uniforms: {
			'float t': () => millis(),
			'vec2 size': () => [width, height],
			'sampler2D data1': () => dataOrder,
			'sampler2D data2': () => dataDisorder,
		},
		'Vertex getWorldInputs': `(Vertex inputs) {
			vec2 coord = vec2(mod(float(gl_InstanceID), 100.), floor(float(gl_InstanceID)/100.))/100.;
   		vec2 pos1 = texture(data1, coord).xy - 0.5;
			vec2 pos2 = texture(data2, coord).xy - 0.5;
			float progress = smoothstep(0., 1., 0.5 * sin(t * 0.0005) + 0.5);
   		inputs.position.xy += mix(pos1, pos2, progress) * size;
	 		float chaos = pow(1. - 2.*abs(progress - 0.5), 0.5) + 0.02;
	 		inputs.position.x += chaos * size.x * 0.01 * sin(t * (0.008 + 0.0001 * mod(float(gl_InstanceID), 50.)) + 0.01 * float(gl_InstanceID));
			inputs.position.y += chaos * size.y * 0.01 * sin(t * (0.006 + 0.0001 * mod(float(gl_InstanceID), 20.)) + 0.007 * float(gl_InstanceID));
			return inputs;
		}`
	})

	remapColors = baseFilterShader().modify(() => {
		getColor((inputs, canvasContent) => {
			const brightness = getTexture(canvasContent, inputs.texCoord).x
			let c = [0, 0, 0, 1]
			let mid = [0.5, 0.5, 1, 1]
			let full = [1, 1, 1, 1]
			if (brightness < 0.5) {
				c = mix(
					c,
					mid,
					brightness * 2
				)
			} else {
				c = mix(
					mid,
					full,
					(brightness - 0.5) * 2
				)
			}
			return c
		})
	})
}

function draw() {
	[prev, next] = [next, prev]
	imageMode(CENTER)
	next.draw(() => {
		background(0)
		push()
		tint(245)
		scale(1.001)
		image(prev, 0, 0)
		pop()
		noStroke()
		fill(255)
		push()
		shader(particleShader)
		model(particle, 5000)
		pop()
		filter(remapColors)
	})
	image(next, 0, 0)
}

